public class Main {
    public static void main(String[] args) {
        System.out.println("Printing multiples of 5 up to 25:");

        for (int i = 5; i <= 25; i += 5) {
            System.out.println("Value: " + i);
        }

        System.out.println("Counting complete!");
    }
}

