practiceProblems.solutionCode:
public class Main {
    public static void main(String[] args) {
        int sum = 0;
        for (int i = 1; i <= 5; i++) {
            sum += i;
        }
        System.out.println("Sum: " + sum);
    }
}

public class Main {
    public static void main(String[] args) {
        for (int i = 15; i >= 3; i -= 3) {
            System.out.print(i + " ");
        }
        System.out.println();
    }
}

public class Main {
    public static void main(String[] args) {
        int fact = 1;
        for (int i = 1; i <= 5; i++) {
            fact *= i;
        }
        System.out.println("5! = " + fact);
    }
}

public class Main {
    public static void main(String[] args) {
        for (int i = 1; i <= 4; i++) {
            System.out.println(i + " squared is " + (i * i));
        }
    }
}

public class Main {
    public static void main(String[] args) {
        for (int i = 1, j = 10; i <= 3; i++, j--) {
            System.out.println("i: " + i + ", j: " + j);
        }
    }
}

public class Main {
    public static void main(String[] args) {
        for (int c = 0; c <= 30; c += 10) {
            int f = (c * 9 / 5) + 32;
            System.out.println(c + "C = " + f + "F");
        }
    }
}

public class Main {
    public static void main(String[] args) {
        int count = 0;
        for (int i = 1; i <= 20; i++) {
            if (i % 4 == 0) {
                count++;
            }
        }
        System.out.println("Total Multiples of 4: " + count);
    }
}
